let text = $input.first().json.output;

// Очистка: убираем блоки кода, кавычки и лишние переносы
text = text
  .replace(/```html/g, '') 
  .replace(/```/g, '')
  .replace(/^"|"$/g, '')
  .replace(/—/g, '-') // Защита от длинных тире
  .trim();

// Получаем ID новости из ноды Get Source Post
const postId = $('Get Source Post').first().json.id;

return [{ json: { content: text, post_id: postId } }];

// Берём данные из триггера
const input = $('Telegram Command and Callback Trigger').first().json;
// ====== ОБРАБОТКА CALLBACK QUERY ======
if (input.callback_query) {
  const callbackData = input.callback_query.data;
  const chatId = input.callback_query.message.chat.id;
  const messageId = input.callback_query.message.message_id;

  // search_more
  if (callbackData === 'search_more') {
    return [{json: {
      action: 'search_more',
      chat_id: chatId,
      message_id: messageId
    }}];
  }

  // generate_post
  if (callbackData.startsWith('generate_post:')) {
    const postId = parseInt(callbackData.split(':')[1]);
    return [{json: {
      action: 'generate_post',
      post_id: postId,
      chat_id: chatId,
      message_id: messageId
    }}];
  }

  // Обработка кнопки видео под готовым постом
  if (callbackData.startsWith('only_video_from_draft:')) {
    const draftId = parseInt(callbackData.split(':')[1]);
    return [{json: {
      action: 'only_video_from_draft',
      draft_id: draftId,
      chat_id: chatId,
      message_id: messageId
    }}];
  }

  // schedule_post
  if (callbackData.startsWith('schedule_post:')) {
    const parts = callbackData.split(':');
    const draftId = parseInt(parts[1]);
    const timeOption = parts[2];
    let scheduledMoscow = $now.setZone('Europe/Moscow');
    if (timeOption === '1h') {
      scheduledMoscow = scheduledMoscow.plus({ hours: 1 });
    } else if (timeOption === '3h') {
      scheduledMoscow = scheduledMoscow.plus({ hours: 3 });
    }
    const scheduledAt = scheduledMoscow.toUTC().toISO();
    return [{json: {
      action: 'schedule_post',
      draft_id: draftId,
      scheduled_at: scheduledAt,
      chat_id: chatId,
      message_id: messageId,
      is_custom_date: false
    }}];
  }

  // publish_now
  if (callbackData.startsWith('publish_now:')) {
    const draftId = parseInt(callbackData.split(':')[1]);
    return [{json: {
      action: 'publish_now',
      draft_id: draftId,
      scheduled_at: $now.toUTC().toISO(),
      chat_id: chatId,
      message_id: messageId,
      is_custom_date: false
    }}];
  }

  // schedule_custom
  if (callbackData.startsWith('schedule_custom:')) {
    const draftId = parseInt(callbackData.split(':')[1]);
    return [{json: {
      action: 'schedule_custom',
      draft_id: draftId,
      chat_id: chatId,
      message_id: messageId
    }}];
  }
}

// ====== ОБРАБОТКА MESSAGE ======
if (input.message) {
  const message = input.message;
  const chatId = message.chat.id;
  const messageId = message.message_id;

  // Команда /search_more БЕЗ reply
  if (!message.reply_to_message) {
    const text = message.text || '';

    if (text.toLowerCase().includes('/search_more')) {
      return [{json: {
        action: 'search_more',
        chat_id: chatId,
        message_id: messageId
      }}];
    }
  }

  // Reply messages
  if (message.reply_to_message) {
    const repliedText = message.reply_to_message.text;
    const repliedMessageId = message.reply_to_message.message_id;

    if (repliedText) {
      // Редактирование поста
      const editMatch = repliedText.match(/\(ID:\s*(\d+)\)/i);
      if (editMatch) {
        const draftId = parseInt(editMatch[1]);
        const newContent = message.text;
        return [{json: {
          action: 'edit_post',
          draft_id: draftId,
          new_content: newContent,
          chat_id: chatId,
          message_id: messageId,
          edit_message_id: repliedMessageId
        }}];
      }

      // Кастомная дата
      const customMatch = repliedText.match(/Draft ID:\s*(\d+)/i);
      if (customMatch && repliedText.includes('Введите дату и время')) {
        const draftId = parseInt(customMatch[1]);
        const userText = message.text;
        const dateRegex = /(\d{2})\.(\d{2})\.(\d{4})\s+(\d{2}):(\d{2})/;
        const dateMatch = userText.match(dateRegex);

        if (dateMatch) {
          const day = dateMatch[1];
          const month = dateMatch[2];
          const year = dateMatch[3];
          const hour = dateMatch[4];
          const minute = dateMatch[5];
          const moscowTime = DateTime.fromObject({
            year: parseInt(year),
            month: parseInt(month),
            day: parseInt(day),
            hour: parseInt(hour),
            minute: parseInt(minute)
          }, { zone: 'Europe/Moscow' });
          const scheduledAt = moscowTime.toUTC().toISO();

          return [{json: {
            action: 'schedule_post',
            draft_id: draftId,
            scheduled_at: scheduledAt,
            chat_id: chatId,
            message_id: messageId,
            edit_message_id: repliedMessageId,
            is_custom_date: true
          }}];
        }
      }
    }
  }
}

// Ничего не подошло - останавливаем
return [];

const action = $('Parse Telegram Callback').item.json.action;
const draftId = $('Parse Telegram Callback').item.json.draft_id;
const publicationId = $input.first().json.id;
const channelName = $('Prepare Settings').item.json.publishing_channel_name;
const scheduledAt = $('Parse Telegram Callback').item.json.scheduled_at;
const isCustomDate = $('Parse Telegram Callback').item.json.is_custom_date || false;
const postContent = $('Load Draft for Publishing').item.json.content;
const telegramMessageId = $('Load Draft for Publishing').item.json.telegram_message_id;

let message = '';

if (action === 'publish_now') {
  message += '━━━━━━━━━━━━

';
  message = '

✅ <b>Пост отправлен в очередь публикации!</b>

';
  message += '━━━━━━━━━━━━

';
  message += postContent + '

';
  message += '━━━━━━━━━━━━

';
  message += '🆔 Publication ID: ' + publicationId + '

';
  message += '📢 Канал: ' + channelName + '

';
  message += '⚡ <i>Публикация произойдёт в ближайшее время</i>

';
} else if (action === 'schedule_post') {
  const scheduledTime = DateTime.fromISO(scheduledAt, { zone: 'utc' });
  const moscowTime = scheduledTime.setZone('Europe/Moscow');
  const timeFormatted = moscowTime.toFormat('dd.MM.yyyy HH:mm');
  message += '━━━━━━━━━━━━

';
  message = '

📅 <b>Публикация запланирована!</b>

';
  message += '⏰ Время: <code>' + timeFormatted + ' (МСК)</code>
';
  message += '📢 Канал: ' + channelName + '

';
  message += '━━━━━━━━━━━━

';
  message += postContent + '

';
  message += '━━━━━━━━━━━━

';
  message += '🆔 Publication ID: ' + publicationId + '

';
  message += '🤖 <i>Бот опубликует автоматически в указанное время</i>

';
}

return [{json: {message: message, chat_id: $('Parse Telegram Callback').item.json.chat_id, message_id: $('Parse Telegram Callback').item.json.message_id, publication_id: publicationId, is_custom_date: isCustomDate, telegram_message_id: telegramMessageId}}];

const input = $input.first().json;
const draftId = input.id;
const content = input.content || "Контент не найден";
const moscowNow = $now.setZone('Europe/Moscow');
const in1h = moscowNow.plus({ hours: 1 });
const in3h = moscowNow.plus({ hours: 3 });
const formatTime = (luxonDate) => {
  return luxonDate.toFormat('HH:mm');
};
const replyMarkup = {
  inline_keyboard: [
    [{text: "✅ Опубликовать сейчас", callback_data: `publish_now:${draftId}`}],
    [{text: `⏱ В ${formatTime(in1h)} МСК`, callback_data: `schedule_post:${draftId}:1h`}, {text: `⏱ В ${formatTime(in3h)} МСК`, callback_data: `schedule_post:${draftId}:3h`}],
    [{text: "📅 Выбрать дату и время", callback_data: `schedule_custom:${draftId}`}]
  ]
};
const messageText = '<b>✅ Пост обновлён!</b>\n\nТекст поста:\n━━━━━━━━━━━━━━━━━━━━\n\n' + content + '\n\n━━━━━━━━━━━━━━━━━━━━\n<b>Для того чтобы отредактировать текст ответьте на это сообщение с новым текстом поста.</b>\n\nЗапланировать публикацию?\n\n<i>Сохранён в черновики (ID: ' + draftId + ')</i>';
return [{json: {id: draftId, content: content, reply_markup: replyMarkup, message_text: messageText, chat_id: $('Parse Telegram Callback').item.json.chat_id, edit_message_id: $('Parse Telegram Callback').item.json.edit_message_id}}];

const now = $now.setZone('Europe/Moscow');
const ex1 = now.plus({days: 1}).set({hour: 14, minute: 0}).toFormat('dd.MM.yyyy HH:mm');
const ex2 = now.plus({days: 3}).set({hour: 10, minute: 30}).toFormat('dd.MM.yyyy HH:mm');
const ex3 = now.plus({days: 7}).set({hour: 18, minute: 0}).toFormat('dd.MM.yyyy HH:mm');

return [{json: {
  chat_id: $input.first().json.chat_id,
  draft_id: $input.first().json.draft_id,
  example1: ex1,
  example2: ex2,
  example3: ex3
}}];

// ПОЛУЧАЕМ ДАННЫЕ ИЗ SETTINGS
const items = $input.all();
const settings = {};

items.forEach(item => {
  const key = item.json.setting_key;
  const value = item.json.setting_value;
  settings[key] = value;
});

// ПОЛУЧАЕМ ДАННЫЕ ИЗ ТРИГГЕРА
const triggerData = $('Telegram Command and Callback Trigger').first().json;

// Возвращаем настройки и входные данные
return [{
  json: {
    ...triggerData,
    admin_chat_id: parseInt(settings.admin_chat_id),
    days_before_ideas: parseInt(settings.days_before_ideas),
    supabase_url: settings.supabase_url,
    default_channel_name: settings.default_channel_name,
    publishing_channel_name: settings.publishing_channel_name,
    publishing_channel_chat_id: settings.publishing_channel_chat_id,
    publishing_channel_identifier: settings.publishing_channel_identifier
  }
}];

const input = $input.first().json;
const draftId = input.id;
const content = input.content || "Контент не найден";
const moscowNow = $now.setZone('Europe/Moscow');
const in1h = moscowNow.plus({ hours: 1 });
const in3h = moscowNow.plus({ hours: 3 });

const formatTime = (luxonDate) => {
  return luxonDate.toFormat('HH:mm');
};

const replyMarkup = {
  inline_keyboard: [
    // 1-й ряд: Кнопка публикации
    [{text: "✅ Опубликовать сейчас", callback_data: `publish_now:${draftId}`}],

    // 2-й ряд: Кнопка генерации видео
    [{text: "🎬 Сгенерировать видео по посту", callback_data: `only_video_from_draft:${draftId}`}],

    // 3-й ряд: Быстрое планирование
    [{text: `⏱ В ${formatTime(in1h)} МСК`, callback_data: `schedule_post:${draftId}:1h`}, {text: `⏱ В ${formatTime(in3h)} МСК`, callback_data: `schedule_post:${draftId}:3h`}],

    // 4-й ряд: Кастомное время
    [{text: "📅 Выбрать дату и время", callback_data: `schedule_custom:${draftId}`}]
  ]
};

return [{json: {id: draftId, content: content, reply_markup: replyMarkup}}];

const input = $input.first().json;

const formats = [
  {
    type: 'expert',
    name: 'Экспертный пост',
    instruction: 'Объясни тему спокойно и профессионально. Дай предпринимателю понятный вывод и практический совет.',
    structure: 'Хук → объяснение ситуации → почему это важно → что проверить → мягкий вопрос в конце.'
  },
  {
    type: 'opinion',
    name: 'Пост с мнением',
    instruction: 'Добавь авторскую позицию. Не просто перескажи новость, а объясни, как это видит опытный предприниматель.',
    structure: 'Хук → позиция автора → аргументы → вывод → вопрос к аудитории.'
  },
  {
    type: 'case',
    name: 'Кейс / ситуация из практики',
    instruction: 'Подай тему как типичную бизнес-ситуацию. Без выдуманных имен и цифр, если их нет в источнике.',
    structure: 'Ситуация → ошибка или риск → последствия → как лучше действовать → вывод.'
  },
  {
    type: 'checklist',
    name: 'Польза / чек-лист',
    instruction: 'Сделай максимально прикладной пост. Дай список действий, что предпринимателю проверить или сделать.',
    structure: 'Хук → короткое объяснение → 3–5 пунктов проверки → итог.'
  },
  {
    type: 'discussion',
    name: 'Пост для обсуждения',
    instruction: 'Сделай пост, который аккуратно вовлекает в комментарии. Без провокаций и желтизны.',
    structure: 'Наблюдение → две стороны вопроса → спокойный вывод → вопрос аудитории.'
  },
  {
    type: 'course_offer',
    name: 'Мягкий продающий пост',
    instruction: 'Свяжи тему с пользой обучения или системного подхода. Не продавай агрессивно. Без прямого давления.',
    structure: 'Проблема → почему важно разобраться → чему стоит научиться → мягкий переход к курсу или обучению.'
  },
  {
    type: 'light_humor',
    name: 'Легкий деловой юмор',
    instruction: 'Добавь легкую иронию, но без сленга, грубости и мемного стиля. Юмор должен быть взрослым и деловым.',
    structure: 'Узнаваемая ситуация → легкая ирония → серьезный вывод → вопрос.'
  }
];

const postId =
  Number($('Get Source Post').first().json.id || 0) ||
  Number(Date.now());

const selected = formats[postId % formats.length];

return [
  {
    json: {
      ...input,
      post_format_type: selected.type,
      post_format_name: selected.name,
      post_format_instruction: selected.instruction,
      post_format_structure: selected.structure
    }
  }
];
